#!/usr/bin/env python3
"""Sync paper Lemma/Theorem numbers from fresco.aux into Rocq + Markdown.

Two responsibilities:

1. Rewrite `Paper Lemma N (Name). [paper-ref: KEY]` comments in .v files
   (KEY is a LaTeX label or `name:"..."` fallback).

2. Regenerate the auto-managed reference-link block in selected Markdown
   files (PROGRESS.md, DESIGN.md, etc.). The block is delimited by:

       <!-- BEGIN paper-refs (auto-generated by scripts/sync_paper_refs.py) -->
       [lemma:foo]: ../paper/sections/bar.tex#L52 "Lemma 3.2: Foo"
       ...
       <!-- END paper-refs -->

   Markdown body uses reference-style links: `[Foo][lemma:foo]`. The
   script rewrites the BEGIN..END region in place with current line
   numbers parsed from `paper/sections/*.tex`.

Usage: `python3 scripts/sync_paper_refs.py [--coq | --md | --all]`
       default: --all.
"""

import argparse
import re
import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[2]
PAPER_AUX = REPO_ROOT / "paper" / "fresco.aux"
PAPER_SECTIONS = REPO_ROOT / "paper" / "sections"
ROCQ_ROOT = REPO_ROOT / "mechanization" / "fresco"
MECH_ROOT = REPO_ROOT / "mechanization"

# Markdown files whose paper-refs block should be regenerated.
MARKDOWN_TARGETS = [
    MECH_ROOT / "PROGRESS.md",
]

# Sections to scan for \label declarations. The "-old" / "-quantifier-rows"
# variants are abandoned drafts — skip them.
TEX_SECTIONS_SKIP = ("-old.tex", "-quantifier-rows.tex")


# --- LaTeX .aux parsing ----------------------------------------------------


def parse_aux(aux_path):
    """Return (label_map, name_map) from a LaTeX .aux file.

    label_map: {LABEL → (Kind, Number, Name)} for entries with stable labels.
    name_map:  {Name → (Kind, Number, Name)} aggregated by visible title,
               used to resolve [paper-ref: name:"..."] references for paper
               restatables that don't expose a custom label.
    """
    if not aux_path.exists():
        sys.exit(f"error: {aux_path} not found. Compile the paper first.")
    text = aux_path.read_text()
    pat = re.compile(
        r"\\newlabel\{([^}]+)\}\{\{([0-9A-Z]+\.[0-9]+)\}\{[^}]*\}\{([^}]*)\}"
        r"\{(lemma|theorem|definition|corollary)\.[0-9A-Z.]+\}\{\}\}"
    )
    label_map = {}
    name_map = {}
    for m in pat.finditer(text):
        label, number, name, kind = m.group(1, 2, 3, 4)
        if not name:
            continue
        entry = (kind.capitalize(), number, name)
        if not label.startswith("thmt@"):
            label_map[label] = entry
        # First occurrence wins for name-based lookup.
        name_map.setdefault(name, entry)
    return label_map, name_map


# --- LaTeX source scanning (label → file:line) -----------------------------


LABEL_LINE_RE = re.compile(r"\\label\{((?:lemma|thm):[^}]+)\}")


def parse_tex_label_lines(sections_dir):
    """Return {label → (relative_path, line_number)}.

    Scans `*.tex` under sections_dir for `\\label{lemma:...}` / `\\label{thm:...}`
    declarations. Skips abandoned variants (see TEX_SECTIONS_SKIP).
    """
    label_lines = {}
    for tex in sorted(sections_dir.glob("*.tex")):
        if any(tex.name.endswith(suffix) for suffix in TEX_SECTIONS_SKIP):
            continue
        rel = tex.relative_to(REPO_ROOT)
        for lineno, line in enumerate(tex.read_text().splitlines(), start=1):
            m = LABEL_LINE_RE.search(line)
            if not m:
                continue
            label = m.group(1)
            if label in label_lines:
                # Duplicate label — prefer the first occurrence and warn.
                prev = label_lines[label]
                print(
                    f"  warning: label '{label}' duplicated: "
                    f"{prev[0]}:{prev[1]} and {rel}:{lineno}",
                    file=sys.stderr,
                )
                continue
            label_lines[label] = (rel, lineno)
    return label_lines


# --- .v file rewriting (Paper Lemma ... [paper-ref: KEY]) ------------------


REF_PATTERN = re.compile(
    r"Paper\s+(Lemma|Theorem|Definition|Corollary)\s+"
    r"[0-9A-Z]+\.[0-9]+(\s*\([^)]*\))?\.\s*"
    r"\[paper-ref:\s*([^\]]+)\]"
)

NAME_REF_RE = re.compile(r'^name:\s*"([^"]+)"$')


def resolve_ref(key, label_map, name_map):
    """Return (kind, number, name) for a [paper-ref: KEY] value, or None."""
    m = NAME_REF_RE.match(key)
    if m:
        return name_map.get(m.group(1))
    return label_map.get(key)


def rewrite_v_file(path, label_map, name_map):
    text = path.read_text()
    changed = False

    def replace(match):
        nonlocal changed
        key = match.group(3).strip()
        entry = resolve_ref(key, label_map, name_map)
        if entry is None:
            print(f"  warning: {path.name}: unknown paper-ref [{key}]")
            return match.group(0)
        kind, number, name = entry
        new = f"Paper {kind} {number} ({name}). [paper-ref: {key}]"
        if new != match.group(0):
            changed = True
        return new

    new_text = REF_PATTERN.sub(replace, text)
    if changed:
        path.write_text(new_text)
        print(f"  updated {path.relative_to(REPO_ROOT)}")


# --- Markdown auto-managed block ------------------------------------------


BEGIN_MARKER = (
    "<!-- BEGIN paper-refs (auto-generated by scripts/sync_paper_refs.py) -->"
)
END_MARKER = "<!-- END paper-refs -->"


def build_markdown_block(label_lines, label_map):
    """Return the body lines for the BEGIN..END region.

    Each line is a markdown reference-link definition:
        [lemma:foo]: ../paper/sections/bar.tex#L52 "Lemma 3.2: Foo"

    Labels present in .tex sources but missing from fresco.aux still get a
    link with the file:line; the title falls back to the label itself.
    """
    lines = []
    # Order labels by (file, line) for deterministic output.
    items = sorted(
        label_lines.items(),
        key=lambda kv: (str(kv[1][0]), kv[1][1]),
    )
    for label, (rel_path, lineno) in items:
        # Build the link target relative to the markdown file's location.
        # PROGRESS.md lives at mechanization/PROGRESS.md → ../paper/...
        link_target = f"../{rel_path}#L{lineno}"
        entry = label_map.get(label)
        if entry is not None:
            kind, number, name = entry
            title = f"{kind} {number}: {name}"
        else:
            title = label
        # Escape any embedded double quotes in the title.
        title_escaped = title.replace('"', "'")
        lines.append(f'[{label}]: {link_target} "{title_escaped}"')
    return lines


def rewrite_md_block(path, body_lines):
    if not path.exists():
        print(f"  warning: {path} not found, skipping markdown sync")
        return
    text = path.read_text()
    if BEGIN_MARKER not in text or END_MARKER not in text:
        # First-time addition: append the block at end of file.
        new = text.rstrip() + "\n\n" + BEGIN_MARKER + "\n"
        new += "\n".join(body_lines) + "\n"
        new += END_MARKER + "\n"
        path.write_text(new)
        print(f"  added paper-refs block to {path.relative_to(REPO_ROOT)}")
        return
    # Replace existing block.
    pattern = re.compile(
        re.escape(BEGIN_MARKER) + r"\n.*?\n" + re.escape(END_MARKER),
        re.DOTALL,
    )
    new_block = (
        BEGIN_MARKER + "\n" + "\n".join(body_lines) + "\n" + END_MARKER
    )
    new = pattern.sub(new_block, text)
    if new != text:
        path.write_text(new)
        print(f"  updated paper-refs block in {path.relative_to(REPO_ROOT)}")


# --- main ------------------------------------------------------------------


def main():
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--coq", action="store_true", help="only rewrite .v files")
    parser.add_argument("--md", action="store_true", help="only rewrite Markdown blocks")
    args = parser.parse_args()
    do_coq = args.coq or not args.md
    do_md = args.md or not args.coq

    label_map, name_map = parse_aux(PAPER_AUX)
    print(
        f"parsed {len(label_map)} labels + {len(name_map)} titles "
        f"from {PAPER_AUX.relative_to(REPO_ROOT)}"
    )

    if do_coq:
        print("rewriting .v files…")
        for v_file in sorted(ROCQ_ROOT.rglob("*.v")):
            rewrite_v_file(v_file, label_map, name_map)

    if do_md:
        print("rewriting Markdown paper-refs blocks…")
        label_lines = parse_tex_label_lines(PAPER_SECTIONS)
        print(f"  found {len(label_lines)} labels in paper/sections/")
        body = build_markdown_block(label_lines, label_map)
        for md_file in MARKDOWN_TARGETS:
            rewrite_md_block(md_file, body)

    print("done.")


if __name__ == "__main__":
    main()
